begin;
-- Passwords and recovery email remain in Supabase Auth, never social tables.
alter table public.profiles add column account_state text not null default 'active' check(account_state in('active','deleting'));
alter table public.profiles add column share_study_stats boolean not null default false;
alter table public.profiles add column friend_chat_enabled boolean not null default false;
grant update(share_study_stats,friend_chat_enabled) on public.profiles to authenticated;
create function public.revision_actor() returns uuid language sql stable security definer set search_path='' as $$select p.user_id from public.profiles p where p.user_id=auth.uid() and p.account_state='active'$$;
revoke all on function public.revision_actor() from public,anon;grant execute on function public.revision_actor() to authenticated,service_role;
create table public.user_handles(user_id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username=lower(username) and username ~ '^[a-z][a-z0-9_]{2,19}$' and username not in('admin','administrator','root','support','moderator','pearson','edexcel','scienceledger','system','security')),created_at timestamptz not null default now());
create table public.friendships(id uuid primary key default gen_random_uuid(),user_low uuid not null references auth.users(id) on delete cascade,user_high uuid not null references auth.users(id) on delete cascade,requester uuid not null references auth.users(id) on delete cascade,status text not null check(status in('pending','accepted','declined','blocked')),blocker uuid references auth.users(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),accepted_at timestamptz,unique(user_low,user_high),check(user_low<user_high),check(requester in(user_low,user_high)),check(blocker is null or blocker in(user_low,user_high)),check((status='blocked')=(blocker is not null)),check(status<>'accepted' or accepted_at is not null));
create index friend_low_idx on public.friendships(user_low,status);create index friend_high_idx on public.friendships(user_high,status);
create table public.study_activity(user_id uuid not null references auth.users(id) on delete cascade,day date not null,active_seconds integer not null default 0 check(active_seconds between 0 and 86400),last_activity_at timestamptz not null,primary key(user_id,day));
create table public.flashcards(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject_code text not null references public.subjects(code),topic_id uuid,front text not null check(length(trim(front)) between 3 and 6000),back text not null check(length(trim(back)) between 1 and 12000),origin text not null check(origin in('learner_authored','original_ai')),validation_status text not null check(validation_status in('user_created','pending','validated','review')),created_at timestamptz not null default now(),unique(id,user_id),foreign key(topic_id,subject_code) references public.topics(id,subject_code));
create table public.flashcard_schedule(card_id uuid primary key,user_id uuid not null,repetitions integer not null default 0 check(repetitions between 0 and 10000),interval_days integer not null default 0 check(interval_days between 0 and 365),ease numeric not null default 2.5 check(ease between 1.3 and 3),due_at timestamptz not null default now(),version integer not null default 0 check(version>=0),foreign key(card_id,user_id) references public.flashcards(id,user_id) on delete cascade);
create table public.flashcard_reviews(event_id uuid primary key,card_id uuid not null,user_id uuid not null,rating text not null check(rating in('again','hard','good','easy')),reviewed_at timestamptz not null default now(),result jsonb not null,foreign key(card_id,user_id) references public.flashcards(id,user_id) on delete cascade);
create index due_cards_idx on public.flashcard_schedule(user_id,due_at);create index cards_owner_idx on public.flashcards(user_id,created_at desc);
create table public.chat_messages(id uuid primary key default gen_random_uuid(),user_low uuid not null references auth.users(id) on delete cascade,user_high uuid not null references auth.users(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,client_message_id uuid not null,body text not null check(length(body) between 1 and 2000 and body ~ '[^[:space:]]'),created_at timestamptz not null default clock_timestamp(),unique(sender_id,client_message_id),check(user_low<user_high),check(sender_id in(user_low,user_high)));
create index chat_conversation_idx on public.chat_messages(user_low,user_high,created_at desc,id desc);
create table public.chat_send_windows(user_id uuid primary key references auth.users(id) on delete cascade,window_start timestamptz not null,used integer not null check(used between 1 and 20));
create table public.chat_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,message_id uuid references public.chat_messages(id) on delete set null,reason text not null check(reason in('spam','harassment','unsafe','other')),details text not null default '' check(length(details)<=500),status text not null default 'open' check(status in('open','reviewed','resolved')),created_at timestamptz not null default now(),unique(reporter_id,message_id));
create table public.login_attempt_windows(key_hash text primary key check(key_hash ~ '^[a-f0-9]{64}$'),window_start timestamptz not null,attempts integer not null check(attempts between 1 and 10));
create table public.objective_sources(topic_id uuid primary key references public.topics(id) on delete cascade,source_text text not null check(length(source_text) between 3 and 12000),source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),pdf_page integer not null check(pdf_page between 1 and 300));
create table public.grade_boundaries(id uuid primary key default gen_random_uuid(),qualification_code text not null references public.science_qualifications(code),series text not null,maximum integer not null check(maximum in(180,330)),entries jsonb not null check(jsonb_typeof(entries)='array'),source_url text not null check(source_url like 'https://qualifications.pearson.com/%'),source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),verified_at timestamptz,unique(qualification_code,series));
create table public.assessment_sets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,qualification_code text not null references public.science_qualifications(code),coverage_reviewed boolean not null default false,difficulty_calibrated boolean not null default false,unseen boolean not null default true,created_at timestamptz not null default now(),unique(id,user_id));
alter table public.mock_exams add column assessment_set_id uuid;
alter table public.mock_exams add constraint mock_set_owner foreign key(assessment_set_id,user_id) references public.assessment_sets(id,user_id);
alter table public.attempts add column answer_version integer not null default 0 check(answer_version>=0);
alter table public.documents add column related_document_id uuid;
alter table public.documents add column upload_expires_at timestamptz;
alter table public.documents add constraint related_document_owner foreign key(related_document_id,user_id) references public.documents(id,user_id);
alter table public.documents add column extraction_summary text;
alter table public.extracted_questions add column ocr_confidence numeric check(ocr_confidence between 0 and 1);
alter table public.extracted_questions add column reviewed_at timestamptz;
alter table public.generated_questions add column origin text not null default 'original_ai' check(origin in('original_ai','private_import'));
alter table public.generated_questions add column source_extracted_id uuid references public.extracted_questions(id);
create table public.question_visuals(question_id uuid primary key references public.generated_questions(id) on delete cascade,data jsonb not null check(jsonb_typeof(data)='array'));
alter table public.jobs add constraint jobs_owner_unique unique(id,user_id);
create table public.job_artifacts(job_id uuid not null,user_id uuid not null,item_index integer not null check(item_index between 0 and 500),data jsonb not null,created_at timestamptz not null default now(),primary key(job_id,item_index),foreign key(job_id,user_id) references public.jobs(id,user_id) on delete cascade);
create table public.ai_request_days(day date primary key,used integer not null check(used>=0));
-- No fictional boundaries or generated learner scores are seeded.
do $$declare t text;begin
 foreach t in array array['user_handles','friendships','study_activity','flashcards','flashcard_schedule','flashcard_reviews','chat_messages','chat_send_windows','chat_reports','login_attempt_windows','objective_sources','grade_boundaries','assessment_sets','question_visuals','job_artifacts','ai_request_days'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 foreach t in array array['user_handles','study_activity','flashcards','flashcard_schedule','flashcard_reviews','assessment_sets'] loop execute format('grant select on public.%I to authenticated',t);execute format('create policy owner_read on public.%I for select to authenticated using(user_id=(select public.revision_actor()))',t);end loop;
 foreach t in array array['profiles','documents','document_pages','extracted_questions','generated_questions','mock_exams','mock_exam_questions','attempts','jobs','usage_counters'] loop execute format('create policy active_owner_read on public.%I as restrictive for select to authenticated using(user_id=(select public.revision_actor()))',t);end loop;
end $$;
create policy active_profile_update on public.profiles as restrictive for update to authenticated using(user_id=(select public.revision_actor())) with check(user_id=(select public.revision_actor()));
grant select on public.friendships to authenticated;create policy friend_participant on public.friendships for select to authenticated using((select public.revision_actor()) in(user_low,user_high) and(status<>'blocked' or blocker=(select public.revision_actor())));
grant select on public.grade_boundaries to authenticated;create policy verified_boundaries on public.grade_boundaries for select to authenticated using(verified_at is not null);
grant select on public.question_visuals to authenticated;create policy visible_visual on public.question_visuals for select to authenticated using(exists(select 1 from public.generated_questions q where q.id=question_id));
create policy hide_unstarted_mock on public.generated_questions as restrictive for select to authenticated using(not exists(select 1 from public.mock_exam_questions mq join public.mock_exams m on m.id=mq.mock_id where mq.question_id=id and m.status in('building','ready')));
create policy active_private_storage_read on storage.objects as restrictive for select to authenticated using(bucket_id<>'revision-private' or public.revision_actor() is not null);
create policy active_private_storage_insert on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'revision-private' or public.revision_actor() is not null);
create function public.claim_username(p_username text) returns public.user_handles language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();name text:=lower(trim(p_username));h public.user_handles;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;if name is null or name !~ '^[a-z][a-z0-9_]{2,19}$' or name in('admin','administrator','root','support','moderator','pearson','edexcel','scienceledger','system','security') then raise exception 'INVALID_USERNAME';end if;
 select * into h from public.user_handles where user_id=actor;if found then if h.username=name then return h;end if;raise exception 'USERNAME_ALREADY_CLAIMED';end if;insert into public.user_handles(user_id,username) values(actor,name) returning * into h;return h;end $$;
create function public.resolve_username_for_login(p_username text) returns uuid language sql stable security definer set search_path='' as $$select h.user_id from public.user_handles h join public.profiles p on p.user_id=h.user_id where h.username=lower(trim(p_username)) and p.account_state='active'$$;
create function public.reserve_login_attempt(p_key text) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin
 if p_key is null or p_key !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_RATE_KEY';end if;
 insert into public.login_attempt_windows values(p_key,clock_timestamp(),1) on conflict(key_hash) do update set attempts=case when public.login_attempt_windows.window_start<clock_timestamp()-interval '10 minutes' then 1 else public.login_attempt_windows.attempts+1 end,window_start=case when public.login_attempt_windows.window_start<clock_timestamp()-interval '10 minutes' then clock_timestamp() else public.login_attempt_windows.window_start end where public.login_attempt_windows.window_start<clock_timestamp()-interval '10 minutes' or public.login_attempt_windows.attempts<10 returning attempts into n;return found;end $$;
create function public.request_friend(p_username text) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();other uuid;f public.friendships;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;if not public.consume_revision_usage(actor,'friend_requests',20) then raise exception 'FRIEND_REQUEST_LIMIT';end if;
 select h.user_id into other from public.user_handles h join public.profiles p on p.user_id=h.user_id where h.username=lower(trim(p_username)) and p.account_state='active';if other is null or other=actor then raise exception 'FRIEND_NOT_AVAILABLE';end if;
 if(select count(*) from public.friendships where actor in(user_low,user_high))>=500 then raise exception 'FRIEND_CAPACITY';end if;
 insert into public.friendships(user_low,user_high,requester,status) values(least(actor,other),greatest(actor,other),actor,'pending') on conflict(user_low,user_high) do nothing;
 select * into f from public.friendships where user_low=least(actor,other) and user_high=greatest(actor,other) for update;if f.status='blocked' then raise exception 'FRIEND_NOT_AVAILABLE';end if;if f.status='pending' and f.requester<>actor then raise exception 'RECEIVED_REQUEST_NEEDS_ACCEPTANCE';end if;
 if f.status='declined' then if f.updated_at>now()-interval '7 days' then raise exception 'FRIEND_REQUEST_COOLDOWN';end if;update public.friendships set status='pending',requester=actor,accepted_at=null,updated_at=now() where id=f.id;end if;return f.id;end $$;
create function public.respond_friend(p_id uuid,p_action text) returns boolean language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();f public.friendships;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;select * into f from public.friendships where id=p_id and actor in(user_low,user_high) for update;if not found or(f.status='blocked' and f.blocker<>actor) then raise exception 'FRIEND_NOT_AVAILABLE';end if;
 if p_action='accept' then if f.status='accepted' then return true;end if;if f.status<>'pending' or f.requester=actor then raise exception 'ACCEPTANCE_NOT_ALLOWED';end if;update public.friendships set status='accepted',accepted_at=now(),updated_at=now() where id=p_id;
 elsif p_action='decline' then if f.status<>'pending' or f.requester=actor then raise exception 'DECLINE_NOT_ALLOWED';end if;update public.friendships set status='declined',updated_at=now() where id=p_id;
 elsif p_action='block' then update public.friendships set status='blocked',blocker=actor,accepted_at=null,updated_at=now() where id=p_id;
 elsif p_action='unblock' then if f.status<>'blocked' or f.blocker<>actor then raise exception 'UNBLOCK_NOT_ALLOWED';end if;delete from public.friendships where id=p_id;
 elsif p_action='remove' then if f.status='blocked' then raise exception 'UNBLOCK_REQUIRED';end if;delete from public.friendships where id=p_id;
 else raise exception 'INVALID_FRIEND_ACTION';end if;return true;end $$;
create function public.list_friends() returns table(friendship_id uuid,other_user_id uuid,username text,status text,requested_by_me boolean) language sql stable security definer set search_path='' as $$select f.id,h.user_id,h.username,f.status,f.requester=public.revision_actor() from public.friendships f join public.user_handles h on h.user_id=case when f.user_low=public.revision_actor() then f.user_high else f.user_low end where public.revision_actor() in(f.user_low,f.user_high) and(f.status<>'blocked' or f.blocker=public.revision_actor()) order by f.created_at desc,f.id$$;
create function public.record_study_activity(p_user uuid) returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.study_activity values(p_user,(now() at time zone 'UTC')::date,0,now()) on conflict(user_id,day) do update set active_seconds=least(86400,public.study_activity.active_seconds+case when now()-public.study_activity.last_activity_at between interval '2 seconds' and interval '60 seconds' then floor(extract(epoch from now()-public.study_activity.last_activity_at))::integer else 0 end),last_activity_at=case when now()-public.study_activity.last_activity_at>=interval '2 seconds' then now() else public.study_activity.last_activity_at end;end $$;
create function public.friend_comparison(p_other uuid) returns table(user_id uuid,username text,active_seconds bigint,assessed_attempts bigint,earned_marks bigint,available_marks bigint) language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();begin
 if actor is null or actor=p_other or not exists(select 1 from public.friendships where user_low=least(actor,p_other) and user_high=greatest(actor,p_other) and status='accepted') then raise exception 'COMPARISON_NOT_AVAILABLE';end if;
 if(select count(*) from public.profiles p where p.user_id in(actor,p_other) and p.share_study_stats and p.account_state='active')<>2 then raise exception 'COMPARISON_NOT_OPTED_IN';end if;
 return query select h.user_id,h.username,coalesce((select sum(s.active_seconds) from public.study_activity s where s.user_id=h.user_id and s.day>=(now() at time zone 'UTC')::date-6),0)::bigint,(select count(*) from public.attempts a join public.marking_runs r on r.id=a.accepted_marking_id where a.user_id=h.user_id and a.status='marked' and r.status='validated'),coalesce((select sum(r.earned_marks) from public.attempts a join public.marking_runs r on r.id=a.accepted_marking_id where a.user_id=h.user_id and a.status='marked' and r.status='validated'),0)::bigint,coalesce((select sum(r.available_marks) from public.attempts a join public.marking_runs r on r.id=a.accepted_marking_id where a.user_id=h.user_id and a.status='marked' and r.status='validated'),0)::bigint from public.user_handles h where h.user_id in(actor,p_other);end $$;
create function public.create_flashcard(p_subject text,p_front text,p_back text,p_topic uuid default null) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();cid uuid;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;if p_subject is null or p_subject not in('4BI1','4CH1','4PH1') or p_front is null or p_back is null or length(trim(p_front)) not between 3 and 6000 or length(trim(p_back)) not between 1 and 12000 then raise exception 'INVALID_FLASHCARD';end if;
 if not public.consume_revision_usage(actor,'new_flashcards',50) then raise exception 'FLASHCARD_LIMIT';end if;insert into public.flashcards(user_id,subject_code,topic_id,front,back,origin,validation_status) values(actor,p_subject,p_topic,trim(p_front),trim(p_back),'learner_authored','user_created') returning id into cid;insert into public.flashcard_schedule(card_id,user_id) values(cid,actor);return cid;end $$;
create function public.review_flashcard(p_card uuid,p_rating text,p_version integer,p_event uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();s public.flashcard_schedule;previous public.flashcard_reviews;days integer;new_ease numeric;reps integer;due timestamptz;result jsonb;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;select * into s from public.flashcard_schedule where card_id=p_card and user_id=actor for update;if not found then raise exception 'FLASHCARD_NOT_FOUND';end if;
 select * into previous from public.flashcard_reviews where event_id=p_event;if found then if previous.user_id<>actor or previous.card_id<>p_card or previous.rating<>p_rating then raise exception 'IDEMPOTENCY_CONFLICT';end if;return previous.result;end if;
 if p_version is null or s.version<>p_version then raise exception 'FLASHCARD_REVIEW_CONFLICT';end if;if p_rating is null or p_rating not in('again','hard','good','easy') or p_event is null then raise exception 'INVALID_RATING';end if;
 if not public.consume_revision_usage(actor,'flashcard_reviews',300) then raise exception 'REVIEW_LIMIT';end if;
 if p_rating='again' then reps:=0;days:=0;new_ease:=greatest(1.3,s.ease-.2);due:=now()+interval '10 minutes';else new_ease:=greatest(1.3,least(3,s.ease+case when p_rating='hard' then -.15 when p_rating='easy' then .15 else 0 end));days:=least(365,case when p_rating='hard' then greatest(1,ceil(s.interval_days*1.2)::integer) when p_rating='easy' then greatest(4,ceil(s.interval_days*new_ease)::integer) when s.repetitions=0 then 1 when s.repetitions=1 then 3 else ceil(s.interval_days*new_ease)::integer end);reps:=least(10000,s.repetitions+1);due:=now()+days*interval '1 day';end if;
 update public.flashcard_schedule set repetitions=reps,interval_days=days,ease=new_ease,due_at=due,version=version+1 where card_id=p_card;result:=jsonb_build_object('card_id',p_card,'repetitions',reps,'interval_days',days,'ease',new_ease,'due_at',due,'version',s.version+1);insert into public.flashcard_reviews values(p_event,p_card,actor,p_rating,now(),result);perform public.record_study_activity(actor);return result;end $$;
create function public.can_friend_chat(p_peer uuid) returns boolean language sql stable security definer set search_path='' as $$select public.revision_actor() is not null and public.revision_actor()<>p_peer and exists(select 1 from public.friendships f where f.user_low=least(public.revision_actor(),p_peer) and f.user_high=greatest(public.revision_actor(),p_peer) and f.status='accepted') and(select count(*) from public.profiles p where p.user_id in(public.revision_actor(),p_peer) and p.friend_chat_enabled and p.account_state='active')=2$$;
grant select on public.chat_messages to authenticated;create policy accepted_chat_read on public.chat_messages for select to authenticated using((select public.revision_actor()) in(user_low,user_high) and public.can_friend_chat(case when user_low=(select public.revision_actor()) then user_high else user_low end));
grant select on public.chat_reports to authenticated;create policy own_report_read on public.chat_reports for select to authenticated using(reporter_id=(select public.revision_actor()));
create function public.send_friend_message(p_peer uuid,p_body text,p_client_message uuid) returns public.chat_messages language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();m public.chat_messages;n integer;last_time timestamptz;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;perform 1 from public.friendships where user_low=least(actor,p_peer) and user_high=greatest(actor,p_peer) and status='accepted' for share;if not found then raise exception 'CHAT_NOT_AVAILABLE';end if;perform 1 from public.profiles where user_id in(actor,p_peer) order by user_id for update;if not public.can_friend_chat(p_peer) then raise exception 'CHAT_NOT_AVAILABLE';end if;
 if p_client_message is null or p_body is null or length(trim(p_body)) not between 1 and 2000 or p_body !~ '[^[:space:]]' or regexp_replace(p_body,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'INVALID_CHAT_MESSAGE';end if;
 select * into m from public.chat_messages where sender_id=actor and client_message_id=p_client_message;if found then if m.user_low<>least(actor,p_peer) or m.user_high<>greatest(actor,p_peer) or m.body<>trim(p_body) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return m;end if;
 insert into public.chat_send_windows values(actor,clock_timestamp(),1) on conflict(user_id) do update set used=case when public.chat_send_windows.window_start<clock_timestamp()-interval '1 minute' then 1 else public.chat_send_windows.used+1 end,window_start=case when public.chat_send_windows.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else public.chat_send_windows.window_start end where public.chat_send_windows.window_start<clock_timestamp()-interval '1 minute' or public.chat_send_windows.used<20 returning used into n;if not found then raise exception 'CHAT_RATE_LIMIT';end if;if not public.consume_revision_usage(actor,'chat_messages',500) then raise exception 'CHAT_DAILY_LIMIT';end if;
 select created_at into last_time from public.chat_messages where user_low=least(actor,p_peer) and user_high=greatest(actor,p_peer) order by created_at desc,id desc limit 1;insert into public.chat_messages(user_low,user_high,sender_id,client_message_id,body,created_at) values(least(actor,p_peer),greatest(actor,p_peer),actor,p_client_message,trim(p_body),greatest(clock_timestamp(),coalesce(last_time+interval '1 microsecond',clock_timestamp()))) returning * into m;return m;end $$;
create function public.get_friend_messages(p_peer uuid,p_cursor_time timestamptz default null,p_cursor_id uuid default null,p_direction text default 'before',p_limit integer default 50) returns table(message_id uuid,sender_id uuid,body text,created_at timestamptz) language plpgsql stable security definer set search_path='' as $$declare actor uuid:=public.revision_actor();begin
 if not public.can_friend_chat(p_peer) then raise exception 'CHAT_NOT_AVAILABLE';end if;if p_limit is null or p_limit not between 1 and 100 or p_direction is null or p_direction not in('before','after') or(p_cursor_time is null)<>(p_cursor_id is null) then raise exception 'INVALID_CHAT_CURSOR';end if;
 if p_direction='after' then return query select m.id,m.sender_id,m.body,m.created_at from public.chat_messages m where m.user_low=least(actor,p_peer) and m.user_high=greatest(actor,p_peer) and(p_cursor_time is null or(m.created_at,m.id)>(p_cursor_time,p_cursor_id)) order by m.created_at,m.id limit p_limit;else return query select m.id,m.sender_id,m.body,m.created_at from public.chat_messages m where m.user_low=least(actor,p_peer) and m.user_high=greatest(actor,p_peer) and(p_cursor_time is null or(m.created_at,m.id)<(p_cursor_time,p_cursor_id)) order by m.created_at desc,m.id desc limit p_limit;end if;end $$;
create function public.report_friend_message(p_message uuid,p_reason text,p_details text default '') returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();rid uuid;begin
 if actor is null then raise exception 'AUTH_REQUIRED';end if;if not exists(select 1 from public.chat_messages where id=p_message and actor in(user_low,user_high)) then raise exception 'MESSAGE_NOT_FOUND';end if;if p_reason is null or p_reason not in('spam','harassment','unsafe','other') or length(coalesce(p_details,''))>500 then raise exception 'INVALID_REPORT';end if;select id into rid from public.chat_reports where reporter_id=actor and message_id=p_message;if found then return rid;end if;if not public.consume_revision_usage(actor,'chat_reports',10) then raise exception 'REPORT_LIMIT';end if;insert into public.chat_reports(reporter_id,message_id,reason,details) values(actor,p_message,p_reason,coalesce(p_details,'')) returning id into rid;return rid;end $$;
create view public.topic_progress with(security_invoker=true) as select a.user_id,q.subject_code,q.topic_id,t.title,t.scope,count(*)::integer attempts,sum(r.earned_marks)::integer earned,sum(r.available_marks)::integer available,(sum(r.earned_marks)::numeric/nullif(sum(r.available_marks),0)) accuracy,sum(a.seconds_spent)::integer seconds_spent from public.attempts a join public.generated_questions q on q.id=a.question_id and q.user_id=a.user_id join public.topics t on t.id=q.topic_id join public.marking_runs r on r.id=a.accepted_marking_id and r.attempt_id=a.id and r.user_id=a.user_id where a.status='marked' and r.status='validated' group by a.user_id,q.subject_code,q.topic_id,t.title,t.scope;
create view public.learning_evidence with(security_invoker=true) as select a.user_id,a.id attempt_id,a.question_id,q.topic_id,r.earned_marks earned,r.available_marks available,a.submitted_at at from public.attempts a join public.generated_questions q on q.id=a.question_id and q.user_id=a.user_id join public.marking_runs r on r.id=a.accepted_marking_id and r.attempt_id=a.id and r.user_id=a.user_id where a.status='marked' and r.status='validated';
revoke all on public.topic_progress,public.learning_evidence from public,anon;grant select on public.topic_progress,public.learning_evidence to authenticated,service_role;
do $$declare f record;begin
 for f in select oid::regprocedure sig,proname from pg_proc where pronamespace='public'::regnamespace and proname in('claim_username','resolve_username_for_login','reserve_login_attempt','request_friend','respond_friend','list_friends','record_study_activity','friend_comparison','create_flashcard','review_flashcard','can_friend_chat','send_friend_message','get_friend_messages','report_friend_message') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);if f.proname not in('resolve_username_for_login','reserve_login_attempt','record_study_activity') then execute format('grant execute on function %s to authenticated',f.sig);end if;end loop;
end $$;
commit;
